const markChatRead = `-- name: MarkChatRead :one
WITH before AS (
    SELECT last_read_at FROM chat_reads WHERE user_id = $1 AND channel_id = $2
)
INSERT INTO chat_reads (user_id, channel_id, last_read_at)
VALUES ($1, $2, $3)
ON CONFLICT (user_id, channel_id) DO UPDATE
SET last_read_at = GREATEST(chat_reads.last_read_at, excluded.last_read_at), updated_at = now()
RETURNING (SELECT coalesce((SELECT last_read_at FROM before), '-infinity'::timestamptz))::timestamptz AS was
`

type MarkChatReadParams struct {
	UserID    pgtype.UUID
	ChannelID pgtype.UUID
	At        pgtype.Timestamptz
}

// Moves how far someone has read, only ever forward; returns where it was before.
func (q *Queries) MarkChatRead(ctx context.Context, arg MarkChatReadParams) (pgtype.Timestamptz, error) {
	row := q.db.QueryRow(ctx, markChatRead, arg.UserID, arg.ChannelID, arg.At)
	var was pgtype.Timestamptz
	err := row.Scan(&was)
	return was, err
}

